import re, collections

def parse(path):
    macros = {}
    cur = None; pin = None; port = None
    stats = collections.Counter()
    with open(path) as f:
        for line in f:
            t = line.split()
            if not t: continue
            if t[0] == 'MACRO':
                cur = {'pins': collections.OrderedDict(), 'obs': 0}
                macros[t[1]] = cur
            elif t[0] == 'PIN' and cur is not None:
                pin = {'dir': None, 'use': None, 'shape': None,
                       'layers': collections.Counter()}
                cur['pins'][t[1]] = pin
            elif t[0] == 'DIRECTION' and pin is not None:
                pin['dir'] = t[1]
            elif t[0] == 'USE' and pin is not None:
                pin['use'] = t[1]
            elif t[0] == 'SHAPE' and pin is not None:
                pin['shape'] = t[1]
            elif t[0] == 'LAYER' and cur is not None:
                if pin is not None and t[1] != 'MET1' or (pin is not None and t[1] == 'MET1'):
                    pass
                if port is not None and pin is not None:
                    pin['layers'][t[1]] += 1
                else:
                    stats['layer_' + t[1]] += 1
            elif t[0] == 'PORT':
                port = pin
            elif t[0] == 'END' and len(t) > 1 and t[1] != cur and pin is not None and t[1] == pin and False:
                pass
            elif line.strip() == 'END':
                port = None
                # closes PORT; PIN closes with "END <name>"
            elif t[0] == 'END' and pin is not None and t[1] == list(cur['pins'])[-1] and False:
                pass
            elif t[0] == 'OBS':
                pin = None  # after OBS, no more pins in this macro
    return macros, stats

# simpler robust parser
def parse2(path):
    macros = {}
    name = None; inpin = None; inport = False
    for line in open(path):
        t = line.split()
        if not t: continue
        if t[0] == 'MACRO':
            name = t[1]; macros[name] = {'pins': collections.OrderedDict()}
            inpin = None; inport = False
        elif t[0] == 'PIN' and name:
            inpin = {'dir':'','use':'','shape':'','layers':collections.Counter()}
            macros[name]['pins'][t[1]] = inpin
        elif t[0] == 'END' and len(t)>1 and name and t[1] in macros[name]['pins']:
            inpin = None; inport = False
        elif t[0] == 'PORT':
            inport = True
        elif line.strip() == 'END':
            inport = False
        elif t[0] == 'OBS':
            inpin = None; inport = False
        elif t[0] == 'DIRECTION' and inpin is not None: inpin['dir'] = t[1]
        elif t[0] == 'USE' and inpin is not None: inpin['use'] = t[1]
        elif t[0] == 'SHAPE' and inpin is not None: inpin['shape'] = t[1]
        elif t[0] == 'LAYER' and inport and inpin is not None: inpin['layers'][t[1]] += 1
    return macros

base = '/home/runner/work/codeReader/codeReader/work/openecos-projects-icsprout55-pdk/IP/STD_cell/ics55_LLSC_H7C_V1p10C100/ics55_LLSC_H7CH/lef/'
A = parse2(base + 'ics55_LLSC_H7CH.lef')
B = parse2(base + 'ics55_LLSC_H7CH_ecos.lef')
print('macros:', len(A), len(B), 'same set:', set(A)==set(B))

pin_dir_mismatch = []
use_mismatch = []
shape_mismatch = []
only_in = []
order_diff = 0
met2_pins = 0; via1_pins = 0; sig_pins = 0
no_met2 = []
for m in A:
    pa, pb = A[m]['pins'], B[m]['pins']
    if list(pa) != list(pb):
        order_diff += 1
    if set(pa) != set(pb):
        only_in.append((m, set(pa)^set(pb)))
    for p in pa:
        if p in pb:
            if pa[p]['dir'] != pb[p]['dir']:
                pin_dir_mismatch.append((m,p,pa[p]['dir'],pb[p]['dir']))
            if pa[p]['use'] != pb[p]['use']:
                use_mismatch.append((m,p,pa[p]['use'],pb[p]['use']))
            if pa[p]['shape'] != pb[p]['shape']:
                shape_mismatch.append((m,p))
            if pb[p]['layers']['MET2']: met2_pins += 1
            if pb[p]['layers']['VIA1']: via1_pins += 1
            if pa[p]['use'] in ('SIGNAL','CLOCK'):
                sig_pins += 1
                if not pb[p]['layers']['MET2']: no_met2.append((m,p))
print('macro pin order differs:', order_diff)
print('pin-set differs:', len(only_in), only_in[:3])
print('DIRECTION mismatches:', len(pin_dir_mismatch), pin_dir_mismatch[:3])
print('USE mismatches:', len(use_mismatch))
um = collections.Counter((x[2],x[3]) for x in use_mismatch)
print('  USE mismatch kinds:', dict(um))
print('  examples:', use_mismatch[:4])
print('SHAPE mismatches:', len(shape_mismatch))
print('signal/clock pins:', sig_pins, '| pins with MET2:', met2_pins, '| pins with VIA1:', via1_pins)
print('signal pins lacking MET2 in ecos:', len(no_met2), no_met2[:5])
